import asyncio


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently, returning results in input order.
    Coroutines not finished within `seconds` are cancelled and their result is None.
    Can be called repeatedly from synchronous code with no running event loop."""
    async def _run_all_with_deadline():
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=seconds)
        # Cancel all pending tasks
        for task in pending:
            task.cancel()
        # Wait for cancellation to complete
        if pending:
            await asyncio.gather(*pending, return_exceptions=True)
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    # Propagate exceptions from finished tasks
                    raise
            else:
                # Timed out tasks return None
                results.append(None)
        return results

    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)
        return loop.run_until_complete(_run_all_with_deadline())
    finally:
        loop.close()
        asyncio.set_event_loop(None)

